ALTER TABLE project_actual_costs DROP CONSTRAINT chk_project_actual_costs_audit, ADD CONSTRAINT chk_project_actual_costs_audit CHECK ((status = 'draft' AND approved_at IS NULL AND approved_by IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND work_section_code_snapshot IS NULL AND work_section_name_snapshot IS NULL AND cost_code_snapshot IS NULL AND cost_code_name_snapshot IS NULL) OR (status = 'approved' AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND work_section_code_snapshot IS NOT NULL AND work_section_name_snapshot IS NOT NULL AND cost_code_snapshot IS NOT NULL AND cost_code_name_snapshot IS NOT NULL) OR (status = 'cancelled' AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL AND approved_at IS NULL AND approved_by IS NULL AND work_section_code_snapshot IS NULL AND work_section_name_snapshot IS NULL AND cost_code_snapshot IS NULL AND cost_code_name_snapshot IS NULL));
